def zcomps8(a):
 R,C=len(a),len(a[0]); seen=set(); ans=[]
 for r in range(R):
  for c in range(C):
   if a[r][c]!=0 or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      if dx==dy==0:continue
      xx,yy=x+dx,y+dy
      if 0<=xx<R and 0<=yy<C and a[xx][yy]==0 and (xx,yy) not in seen:seen.add((xx,yy));q.append((xx,yy))
   ans.append(co)
 return ans
