def metrics(a):
 R,C=len(a),len(a[0]); out=[]
 for co in zcomps(a):
  cells=set(co); n=len(co); rr=[r for r,c in co];cc=[c for r,c in co];
  per=0; adj5=0; boundary=0
  for r,c in co:
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    x,y=r+dr,c+dc
    if 0<=x<R and 0<=y<C:
     if a[x][y]==5:adj5+=1
     if (x,y) not in cells:per+=1
    else:boundary+=1
  out.append((n, (max(rr)-min(rr)+1,max(cc)-min(cc)+1), per,adj5,boundary,tuple(sorted(co))))
 return out
